if fs.exists(loaderPath) then error("Offline bundle cleanup failed: loader remains. Runtime was not started. Re-transfer the original ccminer-offline-gps.lua and parts.", 0) end
print("Offline bundle removed. Keep the original transfer so it can be retransferred for recovery.")
local unpackArgs = table.unpack or unpack
return program(unpackArgs(args))
